import{_ as n,a as d}from"./chunks/song.vmbSg_v5.js";import{_ as r,C as c,o as t,c as i,a2 as o,b as h,w as a,a as l,E as g,a3 as p}from"./chunks/framework.hw3Av5Vn.js";const u="/llamatron/assets/main.BCEbbsBv.svg",A=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"GETTING_STARTED.md","filePath":"GETTING_STARTED.md"}'),m={name:"GETTING_STARTED.md"};function w(f,e,y,k,b,v){const s=c("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This page covers starting llamatron, how every screen is laid out, the keys that work everywhere, the main screen, opening and saving, and building a first song step by step. The page assumes llamatron is installed, as <a href="./INSTALLING">Installing</a> describes.</p><h2 id="starting-llamatron" tabindex="-1">Starting llamatron <a class="header-anchor" href="#starting-llamatron" aria-label="Permalink to &quot;Starting llamatron&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llamatron                                   # a new set with one song, called untitled, playing a starter pattern</span></span>
<span class="line"><span>llamatron examples/learning/08_tie.yml         # open a set file</span></span></code></pre></div><p>Start llamatron from the project folder for now. The Open page starts in <code>examples/</code> when the current folder has one, and new sets are saved into <code>songs/</code> there. Exports are written beside the set&#39;s file, wherever that is.</p><p>A file holds a set of songs, like the songs of one concert. The patterns, scales, generators, chains, grooves and instruments belong to the set, and every song shares them; each song has its own tempo, scale, seed, groove, tracks, registers and scenes.</p><p><a href="https://www.youtube.com/watch?v=JAswLZ8CGzk" target="_blank" rel="noreferrer">A video of moving around the tracker</a> is on YouTube. The video was made with an early build, so some pages look different now, and the program will go on changing.</p><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Every screen is laid out the same way, from top to bottom:</p><ul><li><strong>The header:</strong> where you are at the left, the crumbs, such as <code>PATTERNS › lead</code> or <code>GENERATORS › my arp › OFFSETS</code>, and <code>MAIN SCREEN</code> on the main screen; <code>llamatron</code> in the middle; and at the right the open set, such as <code>set: first.yml</code>, or <code>set: (unsaved)</code> before the set has been saved, with the save mark beside it: <code>● unsaved</code> for a set that has no file yet, <code>● unsaved changes</code> for a set changed since it was saved or opened, and <code>○ saved</code> otherwise. Under the set is the current song, with how long the song, scene, clip or pattern on the page lasts. The version is in the About dialog, <code>F3</code>.</li><li><strong>The page:</strong> a triangle, <code>▶</code>, marks the row the cursor is on, and the arrow keys move it, so you never need to know a key to get around: <code>Enter</code> opens or edits what is marked. Grids mark the selected cell differently: the pattern editor in reverse video, the piano roll by shading the note under the cursor, Arrange with a double-lined box, and the main screen with a box around the selected cell alone. Keys and buttons, the things that act, are shown in reverse video.</li><li><strong>The status line:</strong> one dim line saying what the last key did when that isn&#39;t obvious, such as where a save or an export went, what an undo undid or why a key did nothing. The next key press clears it.</li><li><strong>The legend:</strong> the page&#39;s own keys, each as a reversed label, changing with what is under the cursor. The keys that work on every page aren&#39;t repeated there; <code>F1</code> lists them with the page&#39;s own.</li></ul><h2 id="global-keys" tabindex="-1">Global Keys <a class="header-anchor" href="#global-keys" aria-label="Permalink to &quot;Global Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Ctrl+S</code></td><td>Saves the set.</td></tr><tr><td><code>Ctrl+O</code></td><td>Opens another set, and comes back to the page you were on.</td></tr><tr><td><code>Ctrl+X</code></td><td>Exports the current song, as <a href="./EXPORTING">Exporting</a> describes.</td></tr><tr><td><code>Ctrl+T</code></td><td>The emergency stop for real-time playback: stops whatever plays and sends note offs, all notes off and all sound off on every channel the set&#39;s instruments use, on every connected device, whether or not anything is known to be playing. The status line says what was silenced.</td></tr><tr><td><code>Ctrl+Z</code>, <code>Ctrl+Y</code></td><td>Undo and redo. Only changes to the set count, never moving around: typing into a cell is one change until the cursor moves, a munge is one change, and the notes count when their Save button is pressed. If an undo renames the thing a page shows, the page stays and shows it under its other name; if an undo takes the thing away, the tracker goes back to the page it was opened from and says so.</td></tr><tr><td><code>F1</code></td><td>Every key that works on the page, the keys that work everywhere above the page&#39;s own; <code>Tab</code> turns to a panel saying what the page is for. Keys left off the legend to keep it short, such as <code>Home</code>, <code>End</code> and <code>/</code>, are listed here.</td></tr><tr><td><code>Ctrl+C</code></td><td>Quits at once, from any page or dialog, without asking about unsaved changes, and closes FluidSynth and the MIDI connections as quitting does.</td></tr><tr><td><code>F2</code></td><td>Renames what the page shows or what the cursor is on, as <code>N</code> does.</td></tr><tr><td><code>F3</code></td><td>About llamatron: its version, when it was built, where it lives and its license.</td></tr></tbody></table><p>On a Mac, <code>F1</code>, <code>F2</code> and <code>F3</code> are <code>Fn</code>+<code>F1</code>, <code>Fn</code>+<code>F2</code> and <code>Fn</code>+<code>F3</code> unless System Settings sets the function keys as standard keys.</p><h2 id="keyboard-control" tabindex="-1">Keyboard Control <a class="header-anchor" href="#keyboard-control" aria-label="Permalink to &quot;Keyboard Control&quot;">​</a></h2><p>These hold on every page:</p><ul><li><code>Esc</code> goes back one page at a time and never quits; in a dialog it cancels. Every legend starts with it, then the arrows, then the keys that are always there, then the rest.</li><li><code>Q</code> quits, from the main screen only. With unsaved changes it asks first, and <code>Enter</code> quits without saving.</li><li>A cursor stops at the edges: holding an arrow down takes you to the end and no further.</li><li><code>[</code> (dec) and <code>]</code> (inc) step any value: a number down and up, a cycle of choices back and forward, a gate shorter and longer, and on the piano roll they shrink and stretch the note under the cursor. <code>-</code>, <code>+</code> and <code>=</code> do the same, off the legend, and so do Left and Right on a settings page.</li><li>Anything that is on or off answers to <code>Space</code> and <code>Enter</code> alike, shown as one key, <code>Space/Enter</code>. A row with a short cycle of choices, such as Dot or Register +Note, goes to the next choice on either too.</li><li>Upper and lower case are the same key, and so are <code>Bksp</code> and <code>Delete</code>.</li><li>Nothing is saved or exported until you ask.</li></ul><p><strong>Lists.</strong> Up and Down select. A list you can add to has a <code>+</code> row at the bottom, where <code>Enter</code> adds, as <code>A</code> does. <code>/</code> searches the list as you type: the rows shrink to those containing the text, <code>Tab</code> completes, <code>Enter</code> keeps your place and <code>Esc</code> returns to the whole list. Deleting something still in use is refused, with a list of what uses it; otherwise it asks first. Every list you pick from is sorted by name, while the pages keep the file&#39;s order until <code>S</code> sorts them for good.</p><p><strong>Settings pages.</strong> Up and Down select a setting, <code>[</code> and <code>]</code> change it, <code>Enter</code> types a value or opens a list to choose from, and <code>Bksp</code> clears it where that makes sense. A page with many settings groups some into sections: a heading reads <code>+ Density</code> while closed and <code>- Density</code> while open, <code>Space</code> or <code>Enter</code> toggles it, and <code>PgUp</code> and <code>PgDn</code> jump between headings. Sections start closed and stay as you leave them, by name, for as long as the tracker runs. A closed heading says <code>(set)</code> when anything inside holds a value, so a section never hides a setting silently.</p><p><strong>Dialogs.</strong> In a list, <code>Enter</code> chooses, <code>Esc</code> cancels, typing searches and <code>Tab</code> completes. In a text prompt, Left and Right move the cursor, <code>Bksp</code> erases before it, <code>Enter</code> finishes and <code>Esc</code> cancels; the cursor starts at the end. In a question, <code>Yes</code> and <code>No</code> are buttons that Left and Right move between, <code>Enter</code> presses the marked one, <code>Y</code> and <code>N</code> answer at once, and <code>Esc</code> means no.</p><h2 id="main-screen" tabindex="-1">Main Screen <a class="header-anchor" href="#main-screen" aria-label="Permalink to &quot;Main Screen&quot;">​</a></h2><p><img src="`+u+'" alt="The main screen, showing minimal_techno"></p><p>The main screen is a grid of cells: the pages, four to a row, and below them a row of actions, Save, Open, Export, Import and Quit. Press a cell&#39;s letter, or move the box with the arrows and press <code>Enter</code>. A cell whose page is a list counts what the set holds there. One line under the grid says what the selected cell is for, and the box stays where it was when you come back with <code>Esc</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Page</th><th>What it is for</th></tr></thead><tbody><tr><td><code>F</code></td><td>Set File</td><td>The set&#39;s title, author, description, notes and defaults, with New and Save As</td></tr><tr><td><code>S</code></td><td>Songs</td><td>The songs in the set, and which one is current</td></tr><tr><td><code>P</code></td><td>Patterns</td><td>The notes, in a grid of steps, shared by every song</td></tr><tr><td><code>C</code></td><td>Chains</td><td>Lists of generators that clips, scenes and tracks run</td></tr><tr><td><code>G</code></td><td>Generators</td><td>Every kind of generator</td></tr><tr><td><code>Z</code></td><td>Scales</td><td>The named scales that songs, scenes and clips use</td></tr><tr><td><code>V</code></td><td>Grooves</td><td>Swing and other timing feels</td></tr><tr><td><code>I</code></td><td>Instruments</td><td>The MIDI devices and channels, or FluidSynth, that tracks play through in real time</td></tr><tr><td><code>R</code></td><td>Registers</td><td>AX to DX, four numbers that pattern steps change and use, in the current song</td></tr><tr><td><code>A</code></td><td>Arrange</td><td>The scenes, tracks and clips of the current song. The cell reads Arrange/Play while Real Time is on, since Arrange then plays the song too</td></tr><tr><td><code>T</code></td><td>Real Time</td><td>A switch, not a page: <code>●</code> when the set plays through its instruments in real time, <code>○</code> when not</td></tr><tr><td><code>O</code>, <code>X</code>, <code>M</code></td><td>Open, Export, Import</td><td>On this screen alone, without Ctrl</td></tr><tr><td><code>Q</code></td><td>Quit</td><td>Asks first only when there are unsaved changes</td></tr></tbody></table><p>Registers and Arrange edit the current song, which the Songs page picks. Patterns, Chains, Generators, Scales, Grooves and Instruments belong to the set, so a change there is seen by every song.</p><h2 id="screen-map" tabindex="-1">Screen Map <a class="header-anchor" href="#screen-map" aria-label="Permalink to &quot;Screen Map&quot;">​</a></h2><p>Every screen opens from the main screen, and <code>Esc</code> goes back up the map one step at a time. The Open page opens with <code>Ctrl+O</code> from every page, so it is drawn from the main screen. The label on an arrow is the key that opens the screen; an arrow with no label is a screen opened from a list, with <code>Enter</code> on an item, or in more than one way. The map is generated from the code by <code>internal_tools/make_diagrams.py</code>.</p>',26)),(t(),h(p,null,{default:a(()=>[g(s,{id:"mermaid-370",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20MainPage%5B%22Main%20screen%22%5D%0A%20%20%20%20ArrangePage%5B%22Arrange%22%5D%0A%20%20%20%20ChainsPage%5B%22Chains%22%5D%0A%20%20%20%20FilePage%5B%22Set%20File%22%5D%0A%20%20%20%20GeneratorsPage%5B%22Generators%22%5D%0A%20%20%20%20GroovesPage%5B%22Grooves%22%5D%0A%20%20%20%20InstrumentsPage%5B%22Instruments%22%5D%0A%20%20%20%20OpenPage%5B%22Open%22%5D%0A%20%20%20%20PatternsPage%5B%22Patterns%22%5D%0A%20%20%20%20RegistersPage%5B%22Registers%22%5D%0A%20%20%20%20ScalesPage%5B%22Scales%22%5D%0A%20%20%20%20SongsPage%5B%22Songs%22%5D%0A%20%20%20%20ClipPage%5B%22Clip%22%5D%0A%20%20%20%20PatternEditor%5B%22Pattern%20editor%22%5D%0A%20%20%20%20ScenePage%5B%22Scene%22%5D%0A%20%20%20%20TrackEditor%5B%22Track%20editor%22%5D%0A%20%20%20%20ChainEditor%5B%22Chain%20editor%22%5D%0A%20%20%20%20NotesPage%5B%22Notes%22%5D%0A%20%20%20%20GrooveEditor%5B%22Groove%20editor%22%5D%0A%20%20%20%20InstrumentEditor%5B%22Instrument%20editor%22%5D%0A%20%20%20%20ScalePage%5B%22Scale%22%5D%0A%20%20%20%20SongPage%5B%22Song%22%5D%0A%20%20%20%20ArrangePage%20--%20%22Enter%22%20--%3E%20ClipPage%0A%20%20%20%20ArrangePage%20--%3E%20PatternEditor%0A%20%20%20%20ArrangePage%20--%20%22Enter%22%20--%3E%20ScenePage%0A%20%20%20%20ArrangePage%20--%20%22Enter%22%20--%3E%20TrackEditor%0A%20%20%20%20ChainsPage%20--%3E%20ChainEditor%0A%20%20%20%20ClipPage%20--%3E%20PatternEditor%0A%20%20%20%20FilePage%20--%20%22Enter%22%20--%3E%20NotesPage%0A%20%20%20%20GroovesPage%20--%3E%20GrooveEditor%0A%20%20%20%20InstrumentsPage%20--%3E%20InstrumentEditor%0A%20%20%20%20MainPage%20--%20%22A%22%20--%3E%20ArrangePage%0A%20%20%20%20MainPage%20--%20%22C%22%20--%3E%20ChainsPage%0A%20%20%20%20MainPage%20--%20%22F%22%20--%3E%20FilePage%0A%20%20%20%20MainPage%20--%20%22G%22%20--%3E%20GeneratorsPage%0A%20%20%20%20MainPage%20--%20%22V%22%20--%3E%20GroovesPage%0A%20%20%20%20MainPage%20--%20%22I%22%20--%3E%20InstrumentsPage%0A%20%20%20%20MainPage%20--%20%22Ctrl%2BO%22%20--%3E%20OpenPage%0A%20%20%20%20MainPage%20--%20%22P%22%20--%3E%20PatternsPage%0A%20%20%20%20MainPage%20--%20%22R%22%20--%3E%20RegistersPage%0A%20%20%20%20MainPage%20--%20%22Z%22%20--%3E%20ScalesPage%0A%20%20%20%20MainPage%20--%20%22S%22%20--%3E%20SongsPage%0A%20%20%20%20PatternsPage%20--%3E%20PatternEditor%0A%20%20%20%20ScalesPage%20--%3E%20ScalePage%0A%20%20%20%20SongsPage%20--%3E%20SongPage%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="opening-and-saving" tabindex="-1">Opening and Saving <a class="header-anchor" href="#opening-and-saving" aria-label="Permalink to &quot;Opening and Saving&quot;">​</a></h2><ul><li><strong><code>Ctrl+S</code> saves</strong> the set. The first time, it asks for a file name, starting from <code>songs/untitled.yml</code>, and adds <code>.yml</code> if you leave it off; folders are made as needed. A protected set, such as a demo, is never written over: a dialog offers to save a copy under another name, which isn&#39;t protected. The Set File page&#39;s Protected setting turns the protection off. Saving writes nothing when the file already holds exactly what it would save, and asks before writing over a file something else has changed since it was opened.</li><li><strong><code>W</code> saves as</strong> a new name, on the Set File page, asking before replacing another file.</li><li><strong><code>Ctrl+O</code> opens</strong> a set file. The Open page starts in <code>examples/</code>, where folders show with a trailing slash, such as <code>learning/</code>: <code>Enter</code> opens a file or goes into a folder, and <code>../</code> goes up. A file that holds values llamatron can&#39;t use, such as a velocity of 200 typed in by hand, opens only after a dialog lists each with the value that takes its place: the nearest number allowed, the longest length allowed, or the default. <code>Yes</code> opens the set with those changes, marked unsaved, and the file stays as it is until you save; <code>No</code> opens nothing. Anything else wrong with a file, such as a clip that names a missing pattern, is refused with a message saying where.</li><li><strong><code>N</code> starts</strong> a new set, on the Set File page, with one song called <code>untitled</code> whose first track plays a starter pattern.</li><li><strong><code>Ctrl+X</code> exports</strong> the current song, as <a href="./EXPORTING">Exporting</a> describes, and <strong><code>M</code> imports</strong> a MIDI file as a new song, as <a href="./IMPORTING">Importing</a> describes.</li></ul><p>Opening, starting a new set and quitting ask first when there are unsaved changes.</p><h2 id="first-song" tabindex="-1">First Song <a class="header-anchor" href="#first-song" aria-label="Permalink to &quot;First Song&quot;">​</a></h2><p>This section builds a short song with a melody and a kick drum. A clip needs its pattern and its track to exist first, so the order matters a little.</p><h3 id="_1-check-song-settings" tabindex="-1">1. Check Song Settings <a class="header-anchor" href="#_1-check-song-settings" aria-label="Permalink to &quot;1. Check Song Settings&quot;">​</a></h3><p>Start <code>llamatron</code> with no file. llamatron opens a new set with one song, <code>untitled</code>, which already plays: its one track, <code>track 1</code>, plays <code>pattern 1</code>, a bar of sixteenths with the scale&#39;s root on each beat, in its one scene, <code>scene 1</code>. Press <code>S</code> for Songs, which lists the set&#39;s songs and marks the current one with <code>●</code>:</p><p><img src="'+n+'" alt="The Songs page"></p><p>Press <code>Enter</code> on the song to open its settings:</p><p><img src="'+d+'" alt="A song&#39;s settings"></p><p>A new song is 120 BPM in C major; the pictures show a demo&#39;s song. Change the tempo with <code>[</code> and <code>]</code>, or press <code>Enter</code> and type a number. Leave the rest alone for now, and press <code>Esc</code> twice to go back.</p><h3 id="_2-melody" tabindex="-1">2. Melody <a class="header-anchor" href="#_2-melody" aria-label="Permalink to &quot;2. Melody&quot;">​</a></h3><p>Press <code>P</code> for Patterns, then <code>A</code>, and name the pattern <code>lead</code> in place of the <code>pattern 2</code> it offers. The pattern editor opens on its piano roll with one bar of empty steps, 16 in 4/4, each a sixteenth note. Each row is a note of the scale, labelled down the left, such as <code>E3 3</code> for the E in octave 3, the scale&#39;s third degree. The cursor starts on the root, <code>C3</code>, at step 1.</p><ol><li>Press Up twice, to <code>E3</code>, and press <code>Space</code>. Press Right, then Down once to <code>D3</code> and <code>Space</code>; Right, Down to <code>C3</code> and <code>Space</code>; Right, Up to <code>D3</code> and <code>Space</code>.</li><li><code>Space</code> places a note one step long, drawn as a bar, and never moves the cursor, so you press Right yourself. A step with no note is a rest.</li><li><code>Bksp</code> on a note takes it out again.</li></ol><p>To make a note longer, press <code>]</code> on it to drag its end through one more step, and <code>[</code> to take a step back off, or choose how long placed notes are first with <code>E</code>. The line under the grid describes the note under the cursor, such as <code>Step 1: E3 in C Major, gate 1/16</code>. <code>Tab</code> shows the same notes as rows of values, where the Gate row sets lengths finer than whole steps. <a href="./PATTERNS">Patterns</a> describes the editor in full. Press <code>Esc</code> to go back to the list.</p><h3 id="_3-drum-pattern" tabindex="-1">3. Drum Pattern <a class="header-anchor" href="#_3-drum-pattern" aria-label="Permalink to &quot;3. Drum Pattern&quot;">​</a></h3><p>Press <code>A</code> again and name this one <code>kick</code>. Press <code>R</code> and choose <code>drum on</code> to make it a drum pattern: the top row is now called Note, and takes note letters rather than degrees, since drums follow no scale. Type <code>C</code> on steps 1, 5, 9 and 13. A drum note goes in the set&#39;s default drum octave, octave 1 as Live labels it, so <code>C</code> is C1, MIDI note 36, the first pad of a Drum Rack. Press <code>Esc</code> twice to get back to the main screen.</p><h3 id="_4-tracks" tabindex="-1">4. Tracks <a class="header-anchor" href="#_4-tracks" aria-label="Permalink to &quot;4. Tracks&quot;">​</a></h3><p>Press <code>A</code> for Arrange. A new song starts with one track, <code>track 1</code>, across the top and one scene, <code>scene 1</code>, down the side. Press Up onto the track&#39;s name, then <code>Enter</code>, and rename it <code>lead</code> on the Name field. Press <code>Esc</code>, then move to the <code>+</code> after the last track&#39;s name and press <code>Enter</code> to add <code>track 2</code>, and rename it <code>drums</code> the same way.</p><h3 id="_5-scene-arrangement" tabindex="-1">5. Scene Arrangement <a class="header-anchor" href="#_5-scene-arrangement" aria-label="Permalink to &quot;5. Scene Arrangement&quot;">​</a></h3><p>Scenes are rows and tracks are columns, and a <code>+</code> is an empty cell where a clip can go.</p><ol><li>Move onto <code>scene 1</code>&#39;s <code>lead</code> cell and press <code>Enter</code>. Choose <code>lead</code>; the clip page opens.</li><li>Set Repeat to 4 with <code>]</code>, so the melody plays four times, and press <code>Esc</code>.</li><li>Move onto the <code>drums</code> cell, press <code>Enter</code> and choose <code>kick</code>. Select Loop and press <code>Space</code> to turn it on, so the kick plays for as long as the melody does. Press <code>Esc</code>.</li></ol><p>A scene lasts as long as its longest clip that doesn&#39;t loop, so at least one clip in every scene must not loop. The grid marks the clips: <code>lead ×4</code> repeats and <code>kick ∞</code> loops. To add a second section, press <code>C</code> on the scene&#39;s row to copy the scene below it, then change its clips. <a href="./ARRANGE">Arrange</a> describes the page in full.</p><h3 id="_6-saving-and-exporting" tabindex="-1">6. Saving and Exporting <a class="header-anchor" href="#_6-saving-and-exporting" aria-label="Permalink to &quot;6. Saving and Exporting&quot;">​</a></h3><p>Press <code>Ctrl+S</code> and type a name such as <code>songs/first.yml</code>. Press <code>Ctrl+X</code> and choose Ableton Live set, then open <code>songs/first_untitled.als</code> in Live and put an instrument on each track. To name the song something better than <code>untitled</code>, press <code>S</code> for Songs and <code>N</code> to rename it first.</p><p><a href="./CONCEPTS">Concepts</a> is the next step: moving a figure through chords, shaping sections, adding randomness and performing.</p><p>The demos in <code>examples/learning/</code> are numbered in the order to learn them, each teaching one feature a scene at a time; <a href="./DEMOS">About Demos</a> lists them in that order.</p>',27))])}const S=r(m,[["render",w]]);export{A as __pageData,S as default};
